from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
import re
import json
import hashlib
from collections import Counter

root = Path(__file__).resolve().parents[1]
path = root / 'template261006.tex'
original = path.read_bytes()
text = original.decode('utf-8')
changes = []

def paragraph(prefix, replacement):
    global text
    matches = [line for line in text.splitlines() if line.startswith(prefix)]
    assert len(matches) == 1, (prefix, len(matches))
    old = matches[0]
    assert text.count(old) == 1
    # Every quantity in the edited paragraph must remain present, in order.
    assert Counter(re.findall(r'(?<![A-Za-z_\d])\d+(?:\.\d+)?', old)) == Counter(re.findall(r'(?<![A-Za-z_\d])\d+(?:\.\d+)?', replacement)), prefix
    text = text.replace(old, replacement, 1)
    changes.append(prefix)

paragraph('Recent work has addressed some of these issues', r'''Lightweight architectures such as LU-Net with reverse attention (LU-Net+RA) address some of these challenges through depth-wise separable convolutions and attention to missed regions~\cite{Hernandez2025}. A single feed-forward prediction cannot revise itself. A separate refiner can therefore revisit missed vessel pixels and uncertain boundaries while retaining a fixed coarse predictor. We study a conditional diffusion refiner that receives an LU-Net+RA probability map and the corresponding fundus image, then produces a revised vessel-probability map.''')

paragraph('This work introduces a conditional diffusion model operating', r'''We introduce a conditional diffusion refiner that operates on a spatially downsampled multi-channel representation. Denoising diffusion probabilistic models (DDPMs) support iterative generation and restoration~\cite{Ho2020,Dhariwal2021}; latent diffusion applies these updates within an autoencoder representation~\cite{Rombach2022}. Our representation contains four times as many scalar values as the input mask. Its parameter efficiency therefore concerns the model budget, rather than representation compression. We evaluate segmentation on three retinal datasets and use an explicitly identified published LU-Net+RA configuration for literature context. We also examine how the number of Denoising Diffusion Implicit Model (DDIM) transitions affects accuracy and refinement cost.''')

paragraph('Recent work is more directly related to coarse-to-fine', r'''Several diffusion methods directly address coarse-to-fine refinement. HiDiffSeg combines coarse vessel estimates, vessel skeletons, and fundus-image guidance in a hierarchical retinal segmentation model~\cite{HiDiffSeg}. RefineCatDiff uses coarse probability maps as priors in categorical diffusion~\cite{RefineCatDiff}. Li et al.~\cite{DiffusionFMD} introduce a plug-and-play diffusion denoising module for end-to-end feature-map refinement. Our diffusion refiner applies continuous Gaussian diffusion to encoded LU-Net+RA probabilities, freezes the mask autoencoder, and conditions the denoiser on a global RGB embedding. It functions as a separate post-processing stage. The parameter audit below includes its conditioning layers. These architectural differences do not establish superiority over methods that have not been evaluated in a controlled comparison.''')

paragraph('Unlike formulations that diffuse an encoded ground-truth target', r'''The diffusion refiner adds noise to the encoded coarse mask and uses a decoded Dice loss to encourage agreement with the reference mask. It therefore learns Dice-regularised denoising of coarse predictions, rather than conventional diffusion of encoded ground-truth targets. Section~\ref{sec:spatial_refiner_context} reports a spatial learned-refiner experiment, and Section~\ref{sec:component_ablations} reports controlled component ablations, including target diffusion. A matched comparison with the original diffusion configuration is still needed to isolate its benefit.''')

paragraph('To refine this estimate,', r'''A mask encoder maps the coarse estimate to $\mathbf{z}_0=\mathrm{Encode}(\mathbf{M}_0)$, a spatially downsampled multi-channel representation with $\mathbf{z}_0\in\mathbb{R}^{C\times H\times W}$. The conditional diffusion refiner $\mathrm{Refine}_{\theta}(\cdot)$ iteratively updates this grid using the input image $\mathbf{I}$ as conditioning information. A mask decoder $\mathrm{Decode}(\cdot)$ then maps the refined grid back to pixel space:''')

paragraph('Importantly, this RA mechanism', r'''Reverse attention operates within the LU-Net+RA backbone and influences the coarse prediction $\mathbf{M}_0$. The diffusion refiner receives the encoded coarse mask $\mathbf{z}_0=\mathrm{Encode}(\mathbf{M}_0)$ and image embedding $\mathbf{c}=\mathrm{ImageEncoder}(\mathbf{I}_{RGB})$. It receives no separate RA map or additional RA conditioning channel.''')

paragraph('The previously stated 502,401-parameter', r'''The previously reported 502,401 refinement parameters covered the mask autoencoder (121,409), image encoder (27,712), and diffusion U-Net with internal FiLM projections (353,280). This subtotal omitted the archived implementation's separate 33,024-parameter conditioning MLP. Including it gives 535,425 refinement parameters and 2,482,386 parameters for the complete archived system, or 27.50\% above the baseline. The executable reproduction uses a different time-conditioning MLP with 24,832 parameters. Its refiner contains 527,233 parameters, and its complete system contains 2,474,194, or 27.08\% above the baseline. We report the two implementations separately because their conditioning layers differ.''')

paragraph('These counts quantify storage', r'''These counts describe parameter storage and training budgets. They do not measure computational efficiency: sequential DDIM sampling adds inference work without changing the parameter count. We checked the archived architecture against the available saved model state, but could not establish its link to the deleted original score-producing run. The executable reproduction is linked to retained checkpoints, and Table~\ref{tab:new_denoiser_layers} specifies its denoiser layer by layer.''')

paragraph('We use a lightweight convolutional autoencoder', r'''The convolutional mask autoencoder maps $\mathbf{M}\in\mathbb{R}^{1\times512\times512}$ to $\mathbf{z}\in\mathbb{R}^{64\times128\times128}$, reducing each spatial dimension by $4\times$. The input contains $1\times512\times512=262{,}144$ scalar values; the encoded grid contains $64\times128\times128=1{,}048{,}576$. Thus, spatial downsampling increases the total scalar count. Parameter efficiency refers to the model budget, rather than the size of this representation. The architecture is:''')

paragraph('This RGB conditioning branch is separate', r'''The RGB conditioning branch uses different preprocessing from the coarse LU-Net+RA backbone. The backbone extracts the green channel and enhances contrast to produce $\mathbf{M}_0$. The diffusion image encoder instead receives the resized, normalised three-channel RGB fundus image. This branch supplies colour and illumination information while the denoiser operates on the encoded coarse mask.''')

paragraph('To inject image information into', r'''Learned conditioning layers project the 128-dimensional image embedding $\mathbf{c}$ into the diffusion U-Net's intermediate residual features. The timestep embedding enters through the same residual-block mechanism. This conditioning supplies global image context throughout denoising without a spatial cross-attention map. Reverse attention is confined to the LU-Net+RA backbone that produces $\mathbf{M}_0$; the denoiser receives no separate RA tensor.''')

paragraph('This objective is Dice-regularised', r'''The objective combines two distinct learning signals. The DDPM term predicts Gaussian noise added to $E_m(\mathbf{M}_0)$, encouraging recovery of the encoded coarse mask. The decoded Dice term encourages agreement with the ground-truth vessel mask. This is Dice-regularised coarse-mask denoising, rather than unconditional generation of $E_m(\mathbf{M}_{gt})$ or target diffusion with a separate coarse-mask condition.''')

paragraph('The starting timestep $t_s$ controls', r'''The starting timestep $t_s$ sets the refinement strength. Larger values add more noise and permit greater correction; smaller values preserve more of the LU-Net+RA prediction. Uniform spacing of $S+1$ timesteps between $t_s$ and zero gives exactly $S$ reverse transitions. Each transition evaluates the diffusion U-Net with the image condition and with a null condition, then combines the predictions through classifier-free guidance. A deterministic DDIM update ($\eta_{\mathrm{DDIM}}=0$) advances the feature tensor to the next timestep. The decoder already ends with a sigmoid, so Table~\ref{alg:latent_refinement} applies no second sigmoid. The primary segmentation results use $K=1$. A reverse trajectory is deterministic for a fixed initial noise sample, but the complete procedure varies with that sample.''')

paragraph('The present 50-transition Dice estimates are nominally', r'''The 50-transition Dice estimates exceed the selected published LU-Net+RA values. The 20-transition HRF estimate (0.762), however, is below the published value (0.7756). These studies use different cases and evaluation pipelines, so their differences provide literature context rather than refinement effect estimates. The HRF score at 20 transitions exceeds the within-study baseline of 0.7325 by 0.0295. Within-study comparisons use Table~\ref{tab:segmentation_results} and the author-confirmed protocol matching described above.''')

paragraph('For the three planned comparisons on each dataset', r'''We test three planned comparisons per dataset: baseline versus 50 transitions, 10 versus 50, and 50 versus 100. Two-sided paired $t$ tests and exact Wilcoxon signed-rank tests use the five training-label means. For signed-rank tests, we enumerate all signs, exclude zero differences, and average tied absolute ranks. Holm correction is applied separately to each test type across the nine comparisons. The $t$ test assumes approximately normal independent run-level differences; the signed-rank test assumes independent units and symmetric differences. Five runs provide little evidence for assessing these assumptions, so both analyses are reported.''')

paragraph('Exploratory 95\\% percentile-bootstrap intervals', r'''Exploratory 95\% percentile-bootstrap intervals use 50,000 draws with seed 20261008. We average sampling realisations, then jointly resample training labels and test units. CHASE resampling retains both eyes of each subject together. DRIVE uses image resampling, and HRF uses image resampling within pathology strata. Table~\ref{tab:per_image_paired_intervals} reports the baseline--refinement differences at 50 transitions. With five training labels and four CHASE subjects, interval coverage may be unreliable. Positive bootstrap intervals do not override the nonsignificant subject-level tests.''')

paragraph('For each nonzero weight, we formed', r'''For each nonzero weight, we calculate paired differences $d_s=D_{\lambda,s}-D_{0,s}$ between matching training-seed means. The exploratory 95\% interval is $\overline{d}\pm t_{0.975,2}s_d/\sqrt{3}$, where $s_d$ is the sample standard deviation of the three differences. This paired $t$ interval assumes approximately normal independent training-run differences, an assumption that three seeds cannot reliably assess. It conditions on the fixed test images and five sampling realisations, and therefore excludes uncertainty across images or subjects. Secondary comparisons are exploratory and unadjusted for multiple testing.''')

paragraph('The supplied diffusion means are numerically higher', r'''The supplied diffusion means exceed the spatial-refiner means in Table~\ref{tab:spatial_refiner_context}. Original diffusion checkpoints and prediction records were unavailable, however, so matching score-producing checkpoints and evaluation provenance could not be established. This descriptive comparison does not isolate a diffusion-specific benefit. A matched diffusion--spatial-refiner experiment and same-protocol benchmarks against HiDiffSeg, RefineCatDiff, and Li et al. remain necessary. Architectural differences alone do not establish that reproduction is impossible.''')

paragraph('Each residual block applies GroupNorm', r'''Each residual block applies GroupNorm with eight groups, SiLU, a first convolution, FiLM modulation, a second convolution, and SiLU. The block input is then added to the output. A $128\rightarrow128$ linear projection provides the 64-channel scale and shift. A separate $64\rightarrow128\rightarrow128$ MLP with SiLU projects the 64-dimensional sinusoidal time embedding, which is added to the 128-dimensional global image condition. The denoiser predicts noise. Its residual connections are internal to the blocks; the reference architecture has no additional encoder--decoder concatenation skip.''')

paragraph('The reference diffuses the encoded coarse map', r'''The reference diffusion refiner uses an encoded coarse map, a global 128-dimensional RGB condition with FiLM injection, and a frozen mask autoencoder. The deterministic control directly predicts an encoded-grid residual using a fixed zero time input and decoded Dice loss. It uses no Gaussian denoising or DDIM sampling and differs from the spatial RGB-plus-coarse U-Net in Section~\ref{sec:spatial_refiner_context}. Target diffusion instead encodes the ground-truth training mask. The same target-trained checkpoint is evaluated with noisy-coarse and pure-Gaussian initialisation; no test annotation enters the model. Gaussian initialisation also changes the inference start, so this comparison changes more than one factor. The remaining ablations remove image conditioning, replace the global vector with spatial RGB features and spatial FiLM, replace multiplicative FiLM with additive injection, or jointly fine-tune the mask encoder and decoder.''')

paragraph('The new reference has 405,824', r'''The component-study reference updates 405,824 parameters, a different budget from the archived implementation. The no-image variant updates 378,112 parameters. Joint autoencoder fine-tuning updates 527,233, including 121,409 autoencoder parameters. Global and spatial conditioning have equal parameter counts but different activation and computational costs. Additive injection combines the two FiLM branches as $(g+b)/\sqrt{2}$; this redundant parameterisation does not preserve equal effective capacity. Likewise, the deterministic control has a fixed time input and less time-dependent capacity despite matching the nominal module budget. Ablation latencies were not measured.''')

paragraph('The original author-supplied diffusion results have higher', r'''The original author-supplied diffusion means exceed those of the deterministic encoded-grid refiner and fine-tuned-autoencoder variants on all three datasets (Table~\ref{tab:component_ablations}). Within the matched component study, both variants outperform that study's reference diffusion refiner, although they do not uniformly exceed the coarse baseline. Conditioning changes have small mean effects, with no significant Holm-adjusted paired training-seed $t$ tests. Target diffusion has mixed results with coarse initialisation and poor results with pure-Gaussian initialisation in the tested globally conditioned model. The component-study reference does not reproduce the original supplied diffusion means. The study therefore establishes neither optimality of the original design nor a controlled diffusion advantage over deterministic refinement.''')

paragraph('This protocol isolates the change of refiner-training', r'''The protocol isolates the coarse maps used for refiner training within the executable configuration; it does not replace the original supplied results. Fold baselines use fewer fitting examples, so the comparison also reflects reduced baseline training size. The shared DRIVE autoencoder was pretrained on in-sample coarse maps, and freezing it retains that potential source of shift. Patient independence remains unverified for DRIVE/HRF.''')

paragraph('The proposed refiner is most closely related', r'''The diffusion refiner belongs to the coarse-to-fine family represented by HiDiffSeg~\cite{HiDiffSeg}, RefineCatDiff~\cite{RefineCatDiff}, and the feature-map denoising module of Li et al.~\cite{DiffusionFMD}. Its defining choices are Gaussian diffusion of encoded LU-Net+RA probabilities, a frozen mask autoencoder, and global RGB conditioning. These choices motivate the design; controlled benchmarks are needed to establish an advantage over related methods.''')

paragraph('The 50-transition configuration produced the same', r'''At 50 transitions, reported Dice is 0.835 on both CHASE-DB1 and DRIVE, and 0.793 on HRF. HRF's higher native resolution and mixture of healthy, diabetic-retinopathy, and glaucomatous images may contribute to its lower score, but this explanation has not been tested. On DRIVE, increasing transitions from 20 to 50 improves Dice while the derived false-negative rate rises from 0.165 to 0.175 and the false-positive rate falls from 0.020 to 0.018. This suggests a recall--false-positive trade-off. Because the rates come from rounded summaries, paired confusion counts, threshold sweeps, and vessel-width analysis are needed to identify the underlying changes. On CHASE-DB1, increasing from 50 to 100 transitions adds only 0.001 Dice while approximately doubling refinement time. Each setting uses one initial-noise realisation. The 0.001 difference may therefore reflect sampling variation, but this explanation remains unconfirmed and does not establish an advantage for 100 transitions.''')

paragraph('The method adds an adjustable computational stage', r'''Refinement adds an adjustable inference cost. The original 20- and 50-transition estimates are approximately 40 and 100 ms, and each classifier-free-guidance transition evaluates the diffusion U-Net twice. These estimates exclude the coarse LU-Net+RA forward pass. Section~\ref{sec:pipeline_latency} reports a separate executable benchmark that includes backbone inference and defines its preprocessing and transfer scope.''')

paragraph('The author-confirmed within-study comparisons favour', r'''Author-confirmed within-study comparisons show mean Dice increases of 0.0349 on CHASE-DB1, 0.0471 on DRIVE, and 0.0605 on HRF at 50 transitions. Original per-image diffusion outputs and checkpoint records were unavailable for independent verification of protocol matching. The supplementary analysis in Section~\ref{sec:per_image_uncertainty} uses a distinct source and cannot establish statistical significance for these original comparisons. Assessing their robustness requires verified original paired outputs and repeated training runs. Higher Dice also does not imply improvement in every metric: DRIVE sensitivity decreases relative to the coarse baseline. Published scores in Table~\ref{tab:published_context} provide literature context only.''')

paragraph('Several implementation and evaluation details of the original', r'''The original diffusion records omit settings needed for exact reproduction. These include refinement strength $\rho$, evaluation seed, exact split identities and subject separation, quantitative observer selection, interpolation and aspect-ratio handling, FOV provenance, threshold and DRIVE/HRF aggregation rules, validation and checkpoint selection, batch size and AdamW weight decay, denoiser layers, and timing warm-up and repetition counts. The executable configuration is documented separately and cannot retrospectively establish the original settings. Loss smoothing and reduction conventions also require checking against the implementation before code release.''')

paragraph('The original refiner is trained on in-sample', r'''The original diffusion refiner uses in-sample backbone predictions for training. Section~\ref{sec:oof_protocol} describes a separate matched out-of-fold protocol for the executable implementation. Another potential input shift arises because the mask autoencoder is pretrained on binary annotations but later encodes soft probabilities. The global 128-dimensional image condition also discards spatial features. The $64\times128\times128$ encoded grid reduces spatial resolution while increasing the total scalar count.''')

paragraph('The Dice-weight ablation in Section', r'''The Dice-weight ablation in Section~\ref{sec:dice_weight_ablation} separates the additional supervision term, but its three training seeds and fixed test set do not capture patient-level uncertainty. The component ablations in Section~\ref{sec:component_ablations} evaluate a separate executable configuration and cannot validate the original supplied scores or establish optimality of that design. Similarly, the spatial deterministic-refiner comparison in Section~\ref{sec:spatial_refiner_context} cannot isolate a diffusion-specific benefit. Qualitative cases were selected for visible effects, and centreline, connectivity, boundary, and calibration metrics were not evaluated. Priorities for further work are out-of-fold training maps, paired multi-seed comparisons, topology-aware metrics, unbiased qualitative selection, and benchmarks against recent diffusion refiners.''')

paragraph('This study presents a conditional diffusion module', r'''We present a conditional diffusion refiner for LU-Net+RA vessel probability maps using a spatially downsampled multi-channel representation. The parameter audit gives 535,425 added parameters and 2,482,386 total parameters for the archived implementation. The executable reproduction has 527,233 added parameters and 2,474,194 in total. Both counts include frozen components and conditioning layers. At 50 DDIM transitions, reported Dice is 0.835 on CHASE-DB1, 0.835 on DRIVE, and 0.793 on HRF. CHASE-DB1 Dice ranges from 0.814 at 10 transitions to 0.836 at 100 transitions, showing an adjustable accuracy--cost trade-off for refinement.''')

paragraph('Using the within-study baselines and the author-confirmed', r'''With author-confirmed matching of test images, coarse-predictor checkpoints, and evaluation settings, the 50-transition results exceed the within-study baselines by 0.0349, 0.0471, and 0.0605 Dice on CHASE-DB1, DRIVE, and HRF. These point estimates describe the stated partitions. Verification of the original records and paired repeated-run evaluation are needed to establish statistical significance and robustness. The diffusion refiner provides a focused architecture for further study of retinal vessel refinement.''')

# Edit the wrapped abstract without touching its numerical content.
start = text.index('\\abstract{')
end = text.index('\n', text.index('robustness.}', start))
old_abstract = text[start:end]
new_abstract = r'''\abstract{
Retinal vessel segmentation supports quantitative vascular analysis but remains difficult in low-contrast regions and thin branches. We investigate a conditional diffusion refiner for coarse probability maps from a lightweight U-Net with reverse attention (LU-Net+RA). A frozen mask autoencoder produces a grid with fourfold spatial downsampling. A 128-dimensional global RGB embedding conditions the denoiser, and a frozen decoder reconstructs the refined map after Denoising Diffusion Implicit Model (DDIM) sampling. The refiner applies continuous Gaussian diffusion to the encoded coarse prediction rather than an encoded ground-truth target. The archived implementation contains 535{,}425 refinement parameters, including the frozen autoencoder. At 50 DDIM transitions, Dice point estimates are 0.835, 0.835, and 0.793 on the stated CHASE-DB1, DRIVE, and HRF partitions. The corresponding LU-Net+RA baselines are 0.8001, 0.7879, and 0.7325, giving absolute increases of 0.0349, 0.0471, and 0.0605. Protocol matching is author-confirmed but has not been independently audited against the original diffusion outputs; published scores provide literature context only. On CHASE-DB1, Dice increases from 0.814 to 0.836 as transitions increase from 10 to 100, illustrating an adjustable accuracy--cost trade-off. The design is parameter-efficient, while verified original paired outputs and repeated training runs are needed to assess significance and robustness.}'''
assert re.findall(r'(?<![A-Za-z_\d])\d+(?:\.\d+)?', old_abstract) == re.findall(r'(?<![A-Za-z_\d])\d+(?:\.\d+)?', new_abstract)
text = text[:start] + new_abstract.replace('\n', '\r\n') + text[end:]
changes.append('Abstract')

# Protect mathematical definitions, tables, figures, citations and references.
for env in ('table', 'table*', 'equation', 'equation*', 'align', 'align*', 'figure', 'figure*'):
    pattern = r'\\begin\{' + re.escape(env) + r'\}.*?\\end\{' + re.escape(env) + r'\}'
    assert re.findall(pattern, original.decode('utf-8'), re.S) == re.findall(pattern, text, re.S), env
for command in ('label', 'cite', 'bibitem'):
    pattern = r'\\' + command + r'(?:\[[^\]]*\])?\{([^}]+)\}'
    before = re.findall(pattern, original.decode('utf-8'))
    after = re.findall(pattern, text)
    assert sorted(before) == sorted(after), command
labels = re.findall(r'\\label\{([^}]+)\}', text)
assert len(labels) == len(set(labels)), 'duplicate labels'
assert Counter(re.findall(r'(?<![A-Za-z_\d])\d+(?:\.\d+)?', original.decode('utf-8'))) == Counter(re.findall(r'(?<![A-Za-z_\d])\d+(?:\.\d+)?', text)), 'numerical quantities changed'

stamp = datetime.now(ZoneInfo('Asia/Tehran')).strftime('%Y-%m-%d_%H-%M-%S')
backup = root / f'template261006_before_language_edit_{stamp}.tex'
version = root / f'template261006_{stamp}.tex'
assert not backup.exists() and not version.exists()
backup.write_bytes(original)
updated = text.encode('utf-8')
version.write_bytes(updated)
path.write_bytes(updated)
report = root / 'revise' / f'language_edit_report_{stamp}.json'
report.write_text(json.dumps({'timestamp_Tehran': stamp, 'edited_paragraphs': changes, 'version': str(version), 'prior_copy': str(backup), 'source_sha256': hashlib.sha256(original).hexdigest(), 'version_sha256': hashlib.sha256(updated).hexdigest(), 'checks': ['All numerical quantities unchanged, including occurrence counts', 'Tables, equations and figures unchanged byte-for-byte', 'Citation, bibliography and label inventories unchanged', 'No duplicate labels'], 'pdf_compiled': False}, ensure_ascii=False, indent=2), encoding='utf-8')
print(json.dumps({'version': str(version), 'backup': str(backup), 'paragraphs_edited': len(changes), 'report': str(report)}, ensure_ascii=False))
